export interface OrderSettings
  extends OrderSettingsAllowedActionsOneOf,
    OrderSettingsEditableByOneOf {
  /** Regular order with full set of allowed actions (ActionType for reference). */
  standardActions?: boolean;
  /**
   * View only order with limited set of allowed actions:
   * 1. Add merchant activity
   * 2. Send order notifications
   * 3. Archiving order
   * 4. Assign tags on orders
   * 5. Export order
   * 6. Print order
   */
  limitedActions?: boolean;
  /** Custom list of allowed actions for order. */
  customActions?: CustomAllowedActions;
  /**
   * Allow the order to be editable by any app that has the required permissions.
   * Use when edits are not restricted to owning apps.
   * @internal
   */
  editableByEveryone?: boolean;
  /**
   * Restrict editing of the order to the specified owning apps only.
   * Other apps (even with general edit permissions) are not allowed to edit.
   * @internal
   */
  editableByOwnerApps?: OwnerApps;
  /**
   * New global coupons calculation logic.
   * Indicates which calculation is used for coupons with type `SPECIFIC_ITEMS`.
   * @internal
   */
  specificItemsCouponBehavior?: SpecificItemsCouponBehavior;
  /**
   * Whether to automatically generate an invoice when this order will be PAID.
   * If `false`, no invoice is auto-generated for this order.
   *
   * Default: `true`
   * @internal
   */
  createInvoice?: boolean | null;
}

/** @oneof */
export interface OrderSettingsAllowedActionsOneOf {
  /** Regular order with full set of allowed actions (ActionType for reference). */
  standardActions?: boolean;
  /**
   * View only order with limited set of allowed actions:
   * 1. Add merchant activity
   * 2. Send order notifications
   * 3. Archiving order
   * 4. Assign tags on orders
   * 5. Export order
   * 6. Print order
   */
  limitedActions?: boolean;
  /** Custom list of allowed actions for order. */
  customActions?: CustomAllowedActions;
}

/** @oneof */
export interface OrderSettingsEditableByOneOf {
  /**
   * Allow the order to be editable by any app that has the required permissions.
   * Use when edits are not restricted to owning apps.
   * @internal
   */
  editableByEveryone?: boolean;
  /**
   * Restrict editing of the order to the specified owning apps only.
   * Other apps (even with general edit permissions) are not allowed to edit.
   * @internal
   */
  editableByOwnerApps?: OwnerApps;
}

export interface CustomAllowedActions {
  /** @maxSize 17 */
  orderActions?: OrderActionType[];
}

export enum OrderActionType {
  /** Order is editable */
  EDIT = 'EDIT',
  /** Order is updatable */
  UPDATE = 'UPDATE',
  /** Order is refundable */
  REFUND = 'REFUND',
  /** Allow mark order as approved */
  APPROVE = 'APPROVE',
  /** Allow cancel order */
  CANCEL = 'CANCEL',
  /** Allow fulfill order */
  FULFILL = 'FULFILL',
  /** Allow to collect payment for order */
  COLLECT_PAYMENTS = 'COLLECT_PAYMENTS',
  /** Allow send notifications for order */
  SEND_NOTIFICATIONS = 'SEND_NOTIFICATIONS',
  /** Allow add merchant activities on order */
  ADD_MERCHANT_ACTIVITY = 'ADD_MERCHANT_ACTIVITY',
  /** Allow add all types of activities on order */
  ADD_ACTIVITY = 'ADD_ACTIVITY',
  /** Allow create invoice */
  CREATE_INVOICE = 'CREATE_INVOICE',
  /** Allow create receipts for order payments */
  CREATE_RECEIPTS = 'CREATE_RECEIPTS',
  /** Allow assign tags on order */
  ASSIGN_TAG = 'ASSIGN_TAG',
  /** Allow print packaging slip */
  PRINT_PACKAGING_SLIP = 'PRINT_PACKAGING_SLIP',
  /** Allow to update inventory */
  MODIFY_INVENTORY = 'MODIFY_INVENTORY',
}

export interface OwnerApps {
  /**
   * IDs of the owning apps for this order.
   * @format GUID
   * @minSize 1
   * @maxSize 10
   */
  appIds?: string[];
}

export enum SpecificItemsCouponBehavior {
  /** Coupon calculation behavior was not specified. */
  UNDEFINED_COUPON_BEHAVIOR = 'UNDEFINED_COUPON_BEHAVIOR',
  /** Item subtotal includes coupon discount. */
  ITEM_SUBTOTAL_INCLUDES_DISCOUNT = 'ITEM_SUBTOTAL_INCLUDES_DISCOUNT',
  /**
   * Legacy flow.
   * Discount is applied as to specific items after subtotal calculation.
   */
  LEGACY_ITEM_SUBTOTAL_DOES_NOT_INCLUDE_DISCOUNT = 'LEGACY_ITEM_SUBTOTAL_DOES_NOT_INCLUDE_DISCOUNT',
}

