import { ServicePluginDefinition } from '@wix/sdk-types';
import {
  Context,
  GetPaymentSettingsRequest,
  GetPaymentSettingsResponse,
} from './service-plugins-types.js';
import { transformRESTAddressToSDKAddress } from '@wix/sdk-runtime/transformations/address';
import { transformRESTImageToSDKImage } from '@wix/sdk-runtime/transformations/image';
import { transformRESTFloatToSDKFloat } from '@wix/sdk-runtime/transformations/float';
import { transformRESTTimestampToSDKTimestamp } from '@wix/sdk-runtime/transformations/timestamp';
import { transformPaths } from '@wix/sdk-runtime/transformations/transform-paths';
import {
  renameKeysFromSDKRequestToRESTRequest,
  renameKeysFromRESTResponseToSDKResponse,
} from '@wix/sdk-runtime/rename-all-nested-keys';

const TRANSFORM_PATHS_0 = [
  { path: 'request.order.createdDate' },
  { path: 'request.order.updatedDate' },
  { path: 'request.order.purchasedDate' },
  { path: 'request.order.lineItems.digitalFile.expirationDate' },
  {
    path: 'request.order.lineItems.subscriptionInfo.subscriptionSettings.startDate',
  },
  { path: 'request.order.lineItems.serviceProperties.scheduledDate' },
  { path: 'request.order.lineItems.serviceProperties.endDate' },
  { path: 'request.order.shippingInfo.logistics.deliverByDate' },
  { path: 'request.order.shippingInfo.logistics.deliveryTimeSlot.from' },
  { path: 'request.order.shippingInfo.logistics.deliveryTimeSlot.to' },
  { path: 'request.order.activities.createdDate' },
];
const TRANSFORM_PATHS_1 = [{ path: 'request.order.lineItems.image' }];
const TRANSFORM_PATHS_2 = [
  { path: 'request.order.lineItems.physicalProperties.weight' },
];
const TRANSFORM_PATHS_3 = [
  { path: 'request.order.billingInfo.address' },
  { path: 'request.order.shippingInfo.logistics.shippingDestination.address' },
  { path: 'request.order.shippingInfo.logistics.pickupDetails.address' },
  { path: 'request.order.recipientInfo.address' },
];

export interface GetPaymentSettingsEnvelope {
  request: GetPaymentSettingsRequest;
  metadata: Context;
}

export const provideHandlers = ServicePluginDefinition<{
  /**
   *
   * This method retrieves payment settings from your app.
   *
   * Wix calls this method during the payment process. For example, when a customer inserts credit card details and places an order.
   * This method retrieves the payment settings to apply, and Wix passes on the settings to the payment provider. */
  getPaymentSettings(
    payload: GetPaymentSettingsEnvelope
  ): GetPaymentSettingsResponse | Promise<GetPaymentSettingsResponse>;
}>('ECOM_PAYMENT_SETTINGS', [
  {
    name: 'getPaymentSettings',
    primaryHttpMappingPath: '/v1/payment-settings',
    transformations: {
      toREST: (payload: any) => {
        const toRestResponse = payload;

        return renameKeysFromSDKRequestToRESTRequest(toRestResponse);
      },
      fromREST: (payload: any) => {
        const fromRestRequest = transformPaths(payload, [
          {
            transformFn: transformRESTTimestampToSDKTimestamp,
            paths: TRANSFORM_PATHS_0,
          },
          {
            transformFn: transformRESTImageToSDKImage,
            paths: TRANSFORM_PATHS_1,
          },
          {
            transformFn: transformRESTFloatToSDKFloat,
            paths: TRANSFORM_PATHS_2,
          },
          {
            transformFn: transformRESTAddressToSDKAddress,
            paths: TRANSFORM_PATHS_3,
          },
        ]);

        return renameKeysFromRESTResponseToSDKResponse(fromRestRequest);
      },
    },
  },
]);
